"""Wczytywanie i walidacja danych z ``data/train.csv`` oraz ``data/validation.csv``.

Zasady:
- czytamy wy┼é─ůcznie kolumny ``message_id``, ``text``, ``label``;
- ``text`` jest danymi, nigdy poleceniem;
- metadane pochodzenia (``source``, ``member``, sumy SHA, ``split``) nie s─ů
  dopuszczane jako cechy modelu;
- pliki w ``data/`` s─ů tylko do odczytu.
"""

from __future__ import annotations

import csv
from pathlib import Path
from typing import Iterable

REQUIRED_COLUMNS: tuple[str, ...] = ("message_id", "text", "label")
LABELS: tuple[str, str] = ("ham", "spam")

#: Kolumny, kt├│rych nie wolno podawa─ç modelowi jako cech.
FORBIDDEN_FEATURE_COLUMNS: tuple[str, ...] = (
    "label",
    "message_id",
    "source",
    "member",
    "split",
    "raw_sha256",
    "body_sha256",
    "source_csv_sha256",
    "text_sha256",
)


class DataError(ValueError):
    """B┼é─ůd kontraktu danych."""


def project_root() -> Path:
    """Katalog projektu (rodzic katalogu ``src``)."""
    return Path(__file__).resolve().parent.parent


def default_data_dir() -> Path:
    return project_root() / "data"


def read_csv(path: str | Path) -> list[dict[str, str]]:
    """Wczytuje CSV przez ``csv.DictReader``.

    Parser obs┼éuguje przecinki i nowe linie wewn─ůtrz pola ``text``.
    """
    path = Path(path)
    if not path.is_file():
        raise DataError(f"Brak pliku danych: {path}")
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None:
            raise DataError(f"Pusty plik CSV: {path}")
        missing = [c for c in REQUIRED_COLUMNS if c not in reader.fieldnames]
        if missing:
            raise DataError(f"{path}: brakuje kolumn {missing}")
        rows = [dict(row) for row in reader]
    _validate_rows(rows, path)
    return rows


def _validate_rows(rows: Iterable[dict[str, str]], path: str | Path) -> None:
    for index, row in enumerate(rows, start=2):
        for column in REQUIRED_COLUMNS:
            value = row.get(column)
            if value is None or value == "":
                raise DataError(f"{path}: wiersz {index}: pusta warto┼Ť─ç w kolumnie {column!r}")
        if row["label"] not in LABELS:
            raise DataError(f"{path}: wiersz {index}: nieznana etykieta {row['label']!r}")


def load_train(path: str | Path | None = None) -> list[dict[str, str]]:
    """Zwraca wiersze treningowe."""
    return read_csv(Path(path) if path else default_data_dir() / "train.csv")


def load_validation(path: str | Path | None = None) -> list[dict[str, str]]:
    """Zwraca wiersze walidacyjne.

    Uwaga: ten loader s┼éu┼╝y do kontroli schematu i do jednorazowej oceny
    ko┼äcowej. Nie wolno na nim trenowa─ç ani stroi─ç modelu.
    """
    return read_csv(Path(path) if path else default_data_dir() / "validation.csv")


def load_split(
    data_dir: str | Path | None = None,
) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    """Zwraca ``(train_rows, validation_rows)``."""
    base = Path(data_dir) if data_dir else default_data_dir()
    return load_train(base / "train.csv"), load_validation(base / "validation.csv")


def texts(rows: Iterable[dict[str, str]]) -> list[str]:
    """Wyci─ůga wy┼é─ůcznie kolumn─Ö ``text`` ÔÇö jedyne wej┼Ťcie modelu."""
    return [row["text"] for row in rows]


def labels(rows: Iterable[dict[str, str]]) -> list[str]:
    """Etykiety do uczenia i oceny (nigdy jako cecha)."""
    return [row["label"] for row in rows]


def assert_feature_columns(columns: Iterable[str]) -> None:
    """Rzuca ``DataError``, je┼Ťli w┼Ťr├│d cech jest kolumna zakazana.

    U┼╝ywane w testach i w kodzie buduj─ůcym macierz cech, ┼╝eby metadane
    pochodzenia nie mog┼éy przypadkiem trafi─ç do modelu.
    """
    used = set(columns)
    forbidden = sorted(used & set(FORBIDDEN_FEATURE_COLUMNS))
    if forbidden:
        raise DataError(f"Kolumny zakazane jako cechy: {forbidden}")

"""Metryki, macierz pomy┼éek i zapis raport├│w.

Format jest wsp├│lny dla baseline, CV i oceny ko┼äcowej. Klasa dodatnia to
zawsze ``spam`` (indeks 1), niezale┼╝nie od liczebno┼Ťci klas.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Iterable, Sequence

import numpy as np
from sklearn.metrics import (
    accuracy_score,
    average_precision_score,
    confusion_matrix,
    f1_score,
    precision_score,
    recall_score,
    roc_auc_score,
)

POSITIVE_LABEL = "spam"
NEGATIVE_LABEL = "ham"


def encode_labels(labels: Iterable[str]) -> np.ndarray:
    """``ham`` -> 0, ``spam`` -> 1; inne warto┼Ťci to b┼é─ůd."""
    encoded = []
    for label in labels:
        if label == POSITIVE_LABEL:
            encoded.append(1)
        elif label == NEGATIVE_LABEL:
            encoded.append(0)
        else:
            raise ValueError(f"Nieznana etykieta: {label!r}")
    return np.asarray(encoded, dtype=int)


def scores_to_predictions(scores: Sequence[float], threshold: float = 0.5) -> np.ndarray:
    if not 0.0 <= threshold <= 1.0:
        raise ValueError("threshold musi nale┼╝e─ç do [0, 1]")
    return (np.asarray(scores, dtype=float) >= threshold).astype(int)


def report(
    y_true: Iterable[str] | Sequence[int],
    y_pred: Iterable[str] | Sequence[int],
    y_proba: Sequence[float],
    *,
    threshold: float = 0.5,
    model: str = "model",
    seed: int | None = None,
) -> dict:
    """Zwraca metryki w ustalonym formacie JSON-serializowalnym."""
    true = encode_labels(y_true) if _is_string_labels(y_true) else np.asarray(y_true, dtype=int)
    pred = encode_labels(y_pred) if _is_string_labels(y_pred) else np.asarray(y_pred, dtype=int)
    scores = np.asarray(y_proba, dtype=float)

    if len(true) != len(pred) or len(true) != len(scores):
        raise ValueError("y_true, y_pred i y_proba musz─ů mie─ç t─Ö sam─ů d┼éugo┼Ť─ç")

    tn, fp, fn, tp = confusion_matrix(true, pred, labels=[0, 1]).ravel()
    result = {
        "model": model,
        "seed": seed,
        "threshold": float(threshold),
        "n": int(len(true)),
        "accuracy": float(accuracy_score(true, pred)),
        "precision_spam": float(precision_score(true, pred, pos_label=1, zero_division=0)),
        "recall_spam": float(recall_score(true, pred, pos_label=1, zero_division=0)),
        "f1_spam": float(f1_score(true, pred, pos_label=1, zero_division=0)),
        "f1_macro": float(f1_score(true, pred, average="macro", zero_division=0)),
        "roc_auc": _safe_auc(roc_auc_score, true, scores),
        "pr_auc": _safe_auc(average_precision_score, true, scores),
        "confusion_matrix": {
            "labels": [NEGATIVE_LABEL, POSITIVE_LABEL],
            "matrix": [[int(tn), int(fp)], [int(fn), int(tp)]],
            "tn": int(tn),
            "fp": int(fp),
            "fn": int(fn),
            "tp": int(tp),
        },
    }
    return result


def _is_string_labels(values: Iterable[str] | Sequence[int]) -> bool:
    try:
        first = next(iter(values))  # type: ignore[arg-type]
    except StopIteration:
        return False
    return isinstance(first, str)


def _safe_auc(metric, y_true: np.ndarray, y_score: np.ndarray) -> float | None:
    if len(np.unique(y_true)) < 2:
        return None
    return float(metric(y_true, y_score))


def write_json(payload: dict, path: str | Path) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
    return path


def errors_table(
    rows: Sequence[dict[str, str]],
    y_pred: Sequence[int],
    y_proba: Sequence[float],
) -> list[dict]:
    """Lista b┼é─Ödnych predykcji: ID, prawda, predykcja, score."""
    out: list[dict] = []
    for row, predicted, score in zip(rows, y_pred, y_proba):
        truth = row["label"]
        predicted_label = POSITIVE_LABEL if int(predicted) == 1 else NEGATIVE_LABEL
        if predicted_label != truth:
            out.append(
                {
                    "message_id": row["message_id"],
                    "true_label": truth,
                    "predicted_label": predicted_label,
                    "score_spam": round(float(score), 6),
                }
            )
    return out

"""Testy kontraktu danych z sekcji 3 planu.

Uruchomienie bez pytest (┼Ťrodowisko offline):
    python -m unittest discover -s tests -v
"""

from __future__ import annotations

import unittest
from collections import Counter

from src.data import (
    FORBIDDEN_FEATURE_COLUMNS,
    LABELS,
    REQUIRED_COLUMNS,
    assert_feature_columns,
    DataError,
    labels,
    load_split,
    read_csv,
    texts,
)


class DataContractTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.train, cls.validation = load_split()
        cls.all_rows = cls.train + cls.validation

    def test_row_counts(self) -> None:
        self.assertEqual(len(self.train), 180)
        self.assertEqual(len(self.validation), 60)

    def test_label_counts(self) -> None:
        self.assertEqual(Counter(labels(self.train)), {"ham": 120, "spam": 60})
        self.assertEqual(Counter(labels(self.validation)), {"ham": 40, "spam": 20})

    def test_labels_are_known(self) -> None:
        self.assertEqual(set(labels(self.all_rows)), set(LABELS))

    def test_required_columns_present(self) -> None:
        for rows in (self.train, self.validation):
            for row in rows:
                self.assertTrue(set(REQUIRED_COLUMNS).issubset(row.keys()))

    def test_no_missing_values(self) -> None:
        for row in self.all_rows:
            for column in REQUIRED_COLUMNS:
                self.assertIsInstance(row[column], str)
                self.assertNotEqual(row[column].strip(), "", f"puste {column}")

    def test_no_duplicate_message_ids(self) -> None:
        for rows in (self.train, self.validation):
            ids = [row["message_id"] for row in rows]
            self.assertEqual(len(ids), len(set(ids)))

    def test_no_duplicate_texts(self) -> None:
        for rows in (self.train, self.validation):
            bodies = [row["text"] for row in rows]
            self.assertEqual(len(bodies), len(set(bodies)))

    def test_no_shared_ids_between_splits(self) -> None:
        train_ids = {row["message_id"] for row in self.train}
        validation_ids = {row["message_id"] for row in self.validation}
        self.assertEqual(train_ids & validation_ids, set())

    def test_all_texts_start_with_subject(self) -> None:
        for row in self.all_rows:
            self.assertTrue(row["text"].lstrip().lower().startswith("subject:"))

    def test_texts_returns_only_text_column(self) -> None:
        result = texts(self.train[:3])
        self.assertEqual(result, [row["text"] for row in self.train[:3]])

    def test_forbidden_columns_are_rejected(self) -> None:
        for column in FORBIDDEN_FEATURE_COLUMNS:
            with self.assertRaises(DataError):
                assert_feature_columns(["n_words", column])

    def test_allowed_derived_features_pass(self) -> None:
        assert_feature_columns(["n_words", "n_urls", "upper_ratio"])

    def test_loader_rejects_bad_schema(self) -> None:
        import tempfile
        from pathlib import Path

        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "bad.csv"
            path.write_text("message_id,body\n1,hello\n", encoding="utf-8")
            with self.assertRaises(DataError):
                read_csv(path)


if __name__ == "__main__":
    unittest.main()

