"""TF-IDF + MultinomialNB w czystym Pythonie.

Dlaczego bez scikit-learn: ┼Ťrodowisko jest offline, a pobrane ko┼éowe wersje
scikit-learn zosta┼éy zablokowane przez polityk─Ö Windows Application Control.
Plan (sekcja 5, wariant zapasowy) dopuszcza w┼éasn─ů implementacj─Ö TF-IDF i NB.

Model v1 (E3): TF-IDF word 1ÔÇô2, ``sublinear_tf``, ``smooth_idf`` + MultinomialNB.
Ca┼éa nauka (s┼éownik, IDF, parametry NB) odbywa si─Ö w ``fit`` wy┼é─ůcznie na train.
"""

from __future__ import annotations

import json
import math
import random
import re
from collections import Counter
from pathlib import Path
from typing import Callable, Iterable, Sequence

from . import evaluate
from .data import labels as row_labels
from .data import texts as row_texts

SEED = 2026
MODEL_V1_NAME = "tfidf_word12_multinomialnb_v1"
BASELINE_NAME = "dummy_most_frequent"

TOKEN_RE = re.compile(r"[^\W_]+(?:['ÔÇÖ\-][^\W_]+)*", re.UNICODE)


def tokenize(text: str) -> list[str]:
    return TOKEN_RE.findall(text.lower())


def _ngrams(tokens: Sequence[str], ngram_range: tuple[int, int]) -> list[str]:
    low, high = ngram_range
    terms: list[str] = []
    for n in range(low, high + 1):
        if n == 1:
            terms.extend(tokens)
        elif len(tokens) >= n:
            terms.extend(" ".join(tokens[i:i + n]) for i in range(len(tokens) - n + 1))
    return terms


class TfidfVectorizer:
    """Deterministyczny TF-IDF dla n-gram├│w s┼éownych."""

    def __init__(
        self,
        ngram_range: tuple[int, int] = (1, 2),
        min_df: int = 1,
        sublinear_tf: bool = True,
        smooth_idf: bool = True,
    ) -> None:
        self.ngram_range = (int(ngram_range[0]), int(ngram_range[1]))
        self.min_df = int(min_df)
        self.sublinear_tf = bool(sublinear_tf)
        self.smooth_idf = bool(smooth_idf)
        self.vocabulary_: dict[str, int] = {}
        self.idf_: list[float] = []
        self.n_documents_: int = 0

    def fit(self, documents: Sequence[str]) -> "TfidfVectorizer":
        document_frequency: Counter[str] = Counter()
        for document in documents:
            document_frequency.update(set(_ngrams(tokenize(document), self.ngram_range)))
        terms = sorted(term for term, df in document_frequency.items() if df >= self.min_df)
        self.vocabulary_ = {term: index for index, term in enumerate(terms)}
        n_documents = len(documents)
        self.n_documents_ = n_documents
        if self.smooth_idf:
            self.idf_ = [
                math.log((1.0 + n_documents) / (1.0 + document_frequency[term])) + 1.0
                for term in terms
            ]
        else:
            self.idf_ = [
                math.log(n_documents / max(1, document_frequency[term])) + 1.0 for term in terms
            ]
        return self

    def transform_one(self, document: str) -> dict[int, float]:
        counts = Counter(_ngrams(tokenize(document), self.ngram_range))
        vector: dict[int, float] = {}
        for term, count in counts.items():
            index = self.vocabulary_.get(term)
            if index is None:
                continue
            tf = 1.0 + math.log(count) if self.sublinear_tf else float(count)
            vector[index] = tf * self.idf_[index]
        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm:
            for index in vector:
                vector[index] /= norm
        return vector

    def transform(self, documents: Sequence[str]) -> list[dict[int, float]]:
        return [self.transform_one(document) for document in documents]

    def fit_transform(self, documents: Sequence[str]) -> list[dict[int, float]]:
        return self.fit(documents).transform(documents)

    def to_dict(self) -> dict:
        return {
            "ngram_range": list(self.ngram_range),
            "min_df": self.min_df,
            "sublinear_tf": self.sublinear_tf,
            "smooth_idf": self.smooth_idf,
            "vocabulary": self.vocabulary_,
            "idf": self.idf_,
            "n_documents": self.n_documents_,
        }

    @classmethod
    def from_dict(cls, payload: dict) -> "TfidfVectorizer":
        vectorizer = cls(
            ngram_range=tuple(payload["ngram_range"]),
            min_df=payload["min_df"],
            sublinear_tf=payload["sublinear_tf"],
            smooth_idf=payload["smooth_idf"],
        )
        vectorizer.vocabulary_ = {str(k): int(v) for k, v in payload["vocabulary"].items()}
        vectorizer.idf_ = [float(v) for v in payload["idf"]]
        vectorizer.n_documents_ = int(payload["n_documents"])
        return vectorizer


class MultinomialNB:
    """Multinomial Naive Bayes na rzadkich wektorach (dict index -> value)."""

    def __init__(self, alpha: float = 1.0) -> None:
        self.alpha = float(alpha)
        self.classes_: list[int] = []
        self.log_prior_: list[float] = []
        self.feature_log_prob_: list[list[float]] = []
        self.n_features_: int = 0

    def fit(self, X: Sequence[dict[int, float]], y: Sequence[int]) -> "MultinomialNB":
        self.classes_ = sorted(set(int(label) for label in y))
        self.n_features_ = 1 + max((index for vector in X for index in vector), default=-1)
        class_counts = Counter(int(label) for label in y)
        total = sum(class_counts.values())
        self.log_prior_ = [math.log(class_counts[c] / total) for c in self.classes_]

        feature_log_prob: list[list[float]] = []
        for class_index, class_label in enumerate(self.classes_):
            totals = [0.0] * self.n_features_
            total_count = 0.0
            for vector, label in zip(X, y):
                if int(label) != class_label:
                    continue
                for index, value in vector.items():
                    totals[index] += value
                    total_count += value
            denominator = total_count + self.alpha * self.n_features_
            feature_log_prob.append(
                [math.log((totals[i] + self.alpha) / denominator) for i in range(self.n_features_)]
            )
        self.feature_log_prob_ = feature_log_prob
        return self

    def predict_proba(self, X: Sequence[dict[int, float]]) -> list[list[float]]:
        probabilities: list[list[float]] = []
        for vector in X:
            joints = []
            for class_index in range(len(self.classes_)):
                log_prob = self.log_prior_[class_index]
                weights = self.feature_log_prob_[class_index]
                log_prob += sum(value * weights[index] for index, value in vector.items())
                joints.append(log_prob)
            maximum = max(joints)
            exponentials = [math.exp(value - maximum) for value in joints]
            total = sum(exponentials)
            probabilities.append([value / total for value in exponentials])
        return probabilities

    def to_dict(self) -> dict:
        return {
            "alpha": self.alpha,
            "classes": self.classes_,
            "log_prior": self.log_prior_,
            "feature_log_prob": self.feature_log_prob_,
            "n_features": self.n_features_,
        }

    @classmethod
    def from_dict(cls, payload: dict) -> "MultinomialNB":
        classifier = cls(alpha=payload["alpha"])
        classifier.classes_ = [int(v) for v in payload["classes"]]
        classifier.log_prior_ = [float(v) for v in payload["log_prior"]]
        classifier.feature_log_prob_ = [[float(v) for v in row] for row in payload["feature_log_prob"]]
        classifier.n_features_ = int(payload["n_features"])
        return classifier


class Pipeline:
    def __init__(self, vectorizer: TfidfVectorizer, classifier: MultinomialNB) -> None:
        self.vectorizer = vectorizer
        self.classifier = classifier

    @property
    def classes_(self) -> list[int]:
        return self.classifier.classes_

    def fit(self, texts: Sequence[str], y: Sequence[int]) -> "Pipeline":
        X = self.vectorizer.fit_transform(texts)
        self.classifier.fit(X, y)
        return self

    def predict_proba(self, texts: Sequence[str]) -> list[list[float]]:
        return self.classifier.predict_proba(self.vectorizer.transform(texts))

    def to_dict(self) -> dict:
        return {
            "model": MODEL_V1_NAME,
            "version": 1,
            "vectorizer": self.vectorizer.to_dict(),
            "classifier": self.classifier.to_dict(),
        }

    @classmethod
    def from_dict(cls, payload: dict) -> "Pipeline":
        return cls(
            TfidfVectorizer.from_dict(payload["vectorizer"]),
            MultinomialNB.from_dict(payload["classifier"]),
        )


class DummyClassifier:
    """Zawsze przewiduje najcz─Östsz─ů klas─Ö; score = cz─Östo┼Ť─ç klasy."""

    classes_: list[int]
    prior_: list[float]

    def fit(self, X, y: Sequence[int]) -> "DummyClassifier":
        counts = Counter(int(label) for label in y)
        self.classes_ = sorted(counts)
        total = sum(counts.values())
        self.prior_ = [counts[c] / total for c in self.classes_]
        return self

    def predict_proba(self, X) -> list[list[float]]:
        return [list(self.prior_) for _ in X]


def build_pipeline() -> Pipeline:
    """Model v1: TF-IDF (word 1ÔÇô2) + MultinomialNB."""
    return Pipeline(
        TfidfVectorizer(ngram_range=(1, 2), min_df=1, sublinear_tf=True, smooth_idf=True),
        MultinomialNB(alpha=1.0),
    )


def build_baseline() -> DummyClassifier:
    return DummyClassifier()


def positive_scores(estimator, texts: Sequence[str]) -> list[float]:
    """Zwraca P(spam) dla ka┼╝dego tekstu."""
    if not hasattr(estimator, "predict_proba"):
        raise TypeError("Estymator nie udost─Öpnia predict_proba")
    probabilities = estimator.predict_proba(list(texts))
    classes = list(estimator.classes_)
    if 1 not in classes:
        return [0.0 for _ in texts]
    index = classes.index(1)
    return [float(row[index]) for row in probabilities]


def train_final(rows: Sequence[dict[str, str]], estimator=None):
    """Trenuje model na ca┼éym ``train`` (bez walidacji)."""
    estimator = estimator if estimator is not None else build_pipeline()
    estimator.fit(row_texts(rows), evaluate.encode_labels(row_labels(rows)))
    return estimator


def save_model(estimator, path: str | Path) -> Path:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        json.dump(estimator.to_dict(), handle, ensure_ascii=False)
        handle.write("\n")
    return path


def load_model(path: str | Path) -> Pipeline:
    with Path(path).open("r", encoding="utf-8") as handle:
        return Pipeline.from_dict(json.load(handle))


def stratified_folds(y: Sequence[str], n_splits: int, seed: int) -> list[tuple[list[int], list[int]]]:
    """Podzia┼é stratified o dok┼éadnie zachowanych proporcjach klas."""
    if n_splits < 2:
        raise ValueError("n_splits musi by─ç >= 2")
    rng = random.Random(seed)
    groups: dict[str, list[int]] = {}
    for index, label in enumerate(y):
        groups.setdefault(label, []).append(index)
    chunks: list[list[int]] = [[] for _ in range(n_splits)]
    for label in sorted(groups):
        indices = list(groups[label])
        rng.shuffle(indices)
        for fold_index in range(n_splits):
            chunks[fold_index].extend(indices[fold_index::n_splits])
    folds = []
    all_indices = set(range(len(y)))
    for test_indices in chunks:
        test_set = set(test_indices)
        train_indices = sorted(all_indices - test_set)
        folds.append((train_indices, sorted(test_set)))
    return folds


def cross_validate(
    rows: Sequence[dict[str, str]],
    *,
    estimator_factory: Callable = build_pipeline,
    model_name: str = MODEL_V1_NAME,
    folds: int = 5,
    threshold: float = 0.5,
    seed: int = SEED,
) -> dict:
    """Stratified CV wy┼é─ůcznie na ``train``; metryki per fold + OOF."""
    x = row_texts(rows)
    y = row_labels(rows)
    fold_reports: list[dict] = []
    oof_scores = [0.0] * len(rows)

    for fold_index, (train_idx, test_idx) in enumerate(stratified_folds(y, folds, seed), start=1):
        estimator = estimator_factory()
        estimator.fit([x[i] for i in train_idx], evaluate.encode_labels([y[i] for i in train_idx]))
        scores = positive_scores(estimator, [x[i] for i in test_idx])
        for position, row_index in enumerate(test_idx):
            oof_scores[row_index] = scores[position]
        predictions = evaluate.scores_to_predictions(scores, threshold)
        fold_reports.append(
            evaluate.report(
                [y[i] for i in test_idx],
                predictions,
                scores,
                threshold=threshold,
                model=f"{model_name}_fold{fold_index}",
                seed=seed,
            )
        )

    oof_predictions = evaluate.scores_to_predictions(oof_scores, threshold)
    oof_report = evaluate.report(
        y, oof_predictions, oof_scores, threshold=threshold, model=f"{model_name}_oof", seed=seed
    )

    scalar_keys = [
        "accuracy",
        "precision_spam",
        "recall_spam",
        "f1_spam",
        "f1_macro",
        "roc_auc",
        "pr_auc",
    ]
    mean: dict[str, float | None] = {}
    std: dict[str, float | None] = {}
    for key in scalar_keys:
        values = [fold[key] for fold in fold_reports if fold[key] is not None]
        mean[key] = sum(values) / len(values) if values else None
        if len(values) > 1:
            average = mean[key]
            variance = sum((value - average) ** 2 for value in values) / (len(values) - 1)
            std[key] = math.sqrt(variance)
        else:
            std[key] = 0.0 if values else None

    return {
        "model": model_name,
        "seed": seed,
        "cv_folds": folds,
        "cv_strategy": "StratifiedKFold(shuffle=True)",
        "threshold": threshold,
        "mean": mean,
        "std": std,
        "folds": fold_reports,
        "oof": oof_report,
    }


def baseline_cv(rows: Sequence[dict[str, str]], *, folds: int = 5, seed: int = SEED) -> dict:
    return cross_validate(
        rows,
        estimator_factory=build_baseline,
        model_name=BASELINE_NAME,
        folds=folds,
        threshold=0.5,
        seed=seed,
    )

